const BANK=[{"id": 1, "q": "What should the health care aide do when caring for a client nearing end-of-life?", "opts": ["Provide comfort care only when asked", "Do as much as possible for client", "Ask about their views on death and dying", "Ensure environment is comfortable and well lit"], "a": 2, "e": "Respectfully exploring the client’s beliefs and wishes supports individual care. Let the client decide whether to talk. Comfort care should be proactive; assistance and lighting should match their preferences.", "cat": "Health Across the Life Span", "photo": "01-20260602_204052.jpg", "note": null}, {"id": 2, "q": "What is an example of comfort care the health care aide can provide when caring for a client who is at end-of-life?", "opts": ["Increase frequency of pain medication", "Provide large amounts of easily digested types of food", "Discourage visitors and keep room quiet at all times", "Offer frequent mouth care and ice chips"], "a": 3, "e": "Frequent mouth care helps relieve dryness. Ice chips are appropriate only when the care plan permits them and swallowing is safe. Report pain; do not independently change medication frequency.", "cat": "Provision of Care", "photo": "02-20260602_203824.jpg", "note": null}, {"id": 3, "q": "What document outlines the framework for a health care aide’s (HCA’s) roles and responsibilities?", "opts": ["Health Information Act", "Alberta Health Professions Act", "Alberta HCA Code of Ethics", "Entry Level Competencies for HCAs in Alberta"], "a": 3, "e": "Among these options, the entry-level competencies describe the knowledge, skills, judgment and attitudes expected of an HCA entering practice. Legislation and ethical requirements also govern practice.", "cat": "HCA Role and Responsibility", "photo": "03-20260602_201701.jpg", "note": null}, {"id": 4, "q": "A health care aide speaks to a co-worker in a loud and demanding tone of voice. What type of communication does this represent?", "opts": ["Passive-aggressiveness", "Assertiveness", "Aggression", "Projection"], "a": 2, "e": "Aggression is forceful or intimidating communication. Assertiveness expresses needs directly while respecting others; passive-aggressiveness expresses hostility indirectly.", "cat": "Communication", "photo": "04-20260526_170353.jpg", "note": null}, {"id": 5, "q": "A health care aide is providing care for an 82-year-old client who is immobile. What is the maximum amount of time the client can remain in one position?", "opts": ["1 hour", "2 hours", "3 hours", "4 hours"], "a": 1, "e": "Two hours is the conventional answer intended by this practice item. In real care, there is no single universal maximum: follow the individualized repositioning plan, skin assessment, comfort needs and support surface. Report concerns to the nurse.", "cat": "Safety", "photo": "05-20260526_165213.jpg", "note": "Context-sensitive item: the wording is oversimplified; follow the individualized care plan in practice."}, {"id": 6, "q": "A health care aide (HCA) has been assigned to care for a 4-year-old with fetal alcohol spectrum disorder. What physical sign would the HCA expect to see?", "opts": ["Large tongue", "Finger flicking", "Thin upper lip", "Excessive drooling"], "a": 2, "e": "A thin upper lip is a possible associated facial feature. Many people with FASD do not have distinctive facial features; appearance alone cannot establish a diagnosis.", "cat": "Health Across the Life Span", "photo": "06-20260526_164441.jpg", "note": null}, {"id": 7, "q": "What is one way a health care aide can protect client rights?", "opts": ["Report changes in living conditions", "Provide teaching on medicines when requested", "Report suspected abuse", "Give client information to family"], "a": 2, "e": "Report suspected abuse promptly using the required reporting process; do not wait for proof or investigate independently. Protect immediate safety. Family members do not automatically have permission to receive private information.", "cat": "Safety", "photo": "07-20260526_163329.jpg", "note": null}, {"id": 8, "q": "The health care aide (HCA) was assigned additional clients and informed their supervisor that they were not able to complete all their tasks. What quality did the HCA demonstrate?", "opts": ["Advocacy", "Responsibility", "Positive attitude", "Time management"], "a": 1, "e": "Responsibility includes recognizing limits and promptly communicating when assigned care cannot be completed safely. The supervisor can help reprioritize and arrange assistance.", "cat": "Collaborative Care", "photo": "08-20260526_163009.jpg", "note": null}, {"id": 9, "q": "Following the admission of a new client, what is the priority action for the health care aide?", "opts": ["Assist with medications", "Help client to the shower", "Unpack client’s belongings", "Bring client something to eat"], "a": 2, "e": "With no urgent need stated and only these choices, helping the client settle in by unpacking is the likely intended answer. In actual care, first check immediate safety and comfort, orient the client and review the care plan. Urgent needs take priority.", "cat": "Provision of Care", "photo": "09-20260526_162827.jpg", "note": "Interpretive answer: no official answer key was supplied; immediate clinical needs could change the priority."}, {"id": 10, "q": "A resident says, “I only want my shower in the afternoon.” What is the best response?", "opts": ["Explain that the morning schedule must be followed", "Respect the preference, explore alternatives and inform the team", "Record refusal without discussing options", "Ask a family member to persuade the resident"], "a": 1, "e": "Respect choice and explore an acceptable time or alternative. Communicate the preference so care can be coordinated, and document objectively.", "cat": "Communication", "photo": null, "note": null}, {"id": 11, "q": "A client says, “I am scared I will never go home.” Which reply best demonstrates empathy?", "opts": ["You should try to think positively", "Everyone feels that way at first", "You sound frightened. Would you like to tell me more?", "The nurse will explain the discharge plan later"], "a": 2, "e": "Naming the emotion and inviting the client to speak acknowledges their experience. Avoid dismissing feelings or giving reassurance you cannot support.", "cat": "Communication", "photo": null, "note": null}, {"id": 12, "q": "A co-worker tells you to use a one-person transfer, but the care plan requires two staff. What should you do?", "opts": ["Try it once if the client agrees", "Ask the co-worker to watch from the doorway", "Delay until the next shift without reporting", "Follow the plan, obtain help and raise the concern"], "a": 3, "e": "Do not substitute an unsafe method. Obtain the required help and equipment; communicate delays or concerns.", "cat": "Safety", "photo": null, "note": null}, {"id": 13, "q": "Which statement is the most objective documentation?", "opts": ["Client was difficult and rude", "Client refused lunch and stated, “I feel sick”; nurse notified at 12:10", "Client probably has a stomach infection", "Client did not cooperate as usual"], "a": 1, "e": "Record observations, the client’s words, actions and reporting. Avoid labels, assumptions and diagnoses.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 14, "q": "A family member asks about another resident’s diagnosis. What should you say?", "opts": ["I can tell you if you promise to keep it private", "I cannot share another resident’s private information", "Ask the resident’s roommate", "I can give you a general idea without a name"], "a": 1, "e": "Protect confidentiality. Even partial details can identify a person. Share information only through authorized channels.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 15, "q": "A client with hearing difficulty is struggling to understand you. What is best?", "opts": ["Face the client, reduce background noise and speak clearly", "Shout into the client’s ear", "Talk faster to keep the message short", "Speak to the family instead of the client"], "a": 0, "e": "Facing the client and reducing noise supports understanding. Use a natural, clear voice and check comprehension.", "cat": "Communication", "photo": null, "note": null}, {"id": 16, "q": "You notice a new change in a client’s usual behaviour. What information is most useful when reporting?", "opts": ["Your guess about the diagnosis", "Only that the client is acting strangely", "Specific observations, when they started and the client’s usual baseline", "A co-worker’s opinion about the cause"], "a": 2, "e": "Specific observations and comparison with the usual baseline help the nurse assess the change. Report promptly.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 17, "q": "A client asks you to explain a new medication’s risks. What is best?", "opts": ["Explain what you remember from a different client", "Tell them there are usually no risks", "Advise them to stop taking it", "Refer the question to the nurse or pharmacist and help arrange the conversation"], "a": 3, "e": "Recognize your role and connect the client with the appropriate professional for medication counselling.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 18, "q": "You did not understand an instruction from the nurse. What should you do?", "opts": ["Ask for clarification and repeat back your understanding", "Guess based on the previous shift", "Ask the client to decide what the nurse meant", "Wait until the task is overdue"], "a": 0, "e": "Clarification and read-back reduce misunderstandings. Never guess when the instruction affects care.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 19, "q": "Which question is open-ended?", "opts": ["Did you sleep well?", "Are you in pain?", "How has your morning been?", "Would you like tea?"], "a": 2, "e": "An open-ended question invites a description rather than a yes/no or limited-choice response.", "cat": "Communication", "photo": null, "note": null}, {"id": 20, "q": "An older adult takes longer to complete a familiar task but wishes to do it independently. What is best?", "opts": ["Complete it without asking", "Allow time and offer only the help they need", "Assume they can no longer manage any tasks", "Discourage them from trying"], "a": 1, "e": "Support abilities and preferences without making age-based assumptions. Allow time while observing safety.", "cat": "Health Across the Life Span", "photo": null, "note": null}, {"id": 21, "q": "You disagree with a colleague’s suggestion. Which reply is assertive?", "opts": ["That is a terrible idea", "Fine, whatever you want", "I am concerned this conflicts with the care plan. Let’s check with the nurse", "Say nothing, then complain to other staff"], "a": 2, "e": "Assertive communication states a concern clearly and respectfully and seeks a safe solution.", "cat": "Communication", "photo": null, "note": null}, {"id": 22, "q": "A client needs an interpreter for an important care discussion. What should you do?", "opts": ["Use a child family member", "Speak louder in English", "Skip the discussion and complete the care", "Arrange an approved interpreter through the team"], "a": 3, "e": "An approved interpreter supports accurate communication and privacy. Continue addressing the client directly.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 23, "q": "A co-worker asks you to document care they have not yet provided. What should you do?", "opts": ["Document it if they are usually reliable", "Refuse to record care not provided and raise the concern appropriately", "Write it in pencil", "Record it and change it later if needed"], "a": 1, "e": "Records must be truthful and reflect care actually provided. Follow policy for reporting the concern.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 24, "q": "A client says a staff member hurt them and asks you to keep it secret. What is best?", "opts": ["Promise secrecy to build trust", "Ask them to confront the staff member", "Listen calmly, explain that safety concerns must be reported and report promptly", "Wait for another client to confirm the story"], "a": 2, "e": "Do not promise secrecy about abuse. Listen without leading questions, record facts and follow required reporting procedures.", "cat": "Safety", "photo": null, "note": null}, {"id": 25, "q": "A client becomes angry during care. What should you do first?", "opts": ["Argue until they understand", "Speak calmly, allow space and check safety", "Continue the task quickly", "Tell them they are being unreasonable"], "a": 1, "e": "A calm manner and personal space can reduce escalation. Pause care and seek help if safety is threatened.", "cat": "Communication", "photo": null, "note": null}, {"id": 26, "q": "A task is outside your training and authorization. The unit is short-staffed. What should you do?", "opts": ["Perform it because the unit needs help", "Ask another untrained aide to guide you", "Explain your limits to the supervisor and request an appropriate assignment", "Let the client teach you"], "a": 2, "e": "Staffing pressure does not establish competence or authorization. Communicate your limits and arrange suitable help.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 27, "q": "A client can wash their own face but needs help with the rest of bathing. What is best?", "opts": ["Wash everything to save time", "Encourage the client to wash their face and assist where needed", "Leave them to complete the entire bath alone", "Ask them not to participate because they may get tired"], "a": 1, "e": "Support safe independence and personal choice, while providing the assistance in the care plan.", "cat": "Provision of Care", "photo": null, "note": null}, {"id": 28, "q": "Before beginning personal care, which action best supports dignity and consent?", "opts": ["Start while explaining later", "Ask the roommate to decide", "Explain the care, obtain consent and provide privacy", "Leave the door open to save time"], "a": 2, "e": "Explain the task and seek consent before care. Curtains, doors and appropriate covering protect dignity.", "cat": "Provision of Care", "photo": null, "note": null}, {"id": 29, "q": "You are interrupted before completing a scheduled care task. What is best at handover?", "opts": ["Assume the next shift will notice", "Mark the task complete to avoid confusion", "Clearly report the outstanding care and any concerns to the appropriate staff", "Wait until someone asks"], "a": 2, "e": "Clear handover helps prevent missed care. Communicate outstanding tasks promptly and record accurately according to policy.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 30, "q": "A client’s cultural practice is unfamiliar to you. What is the best approach?", "opts": ["Assume all members of that culture have the same preferences", "Ask respectfully about the client’s preferences and coordinate safe care", "Explain that facility routines always come first", "Avoid mentioning it"], "a": 1, "e": "Ask the individual rather than relying on stereotypes. Work with the team to respect preferences while meeting care needs.", "cat": "Communication", "photo": null, "note": null}, {"id": 31, "q": "A nurse asks whether a resident ate breakfast. You did not observe the meal. What should you say?", "opts": ["They probably ate as usual", "State that you did not observe it and help locate accurate information", "Say they ate to avoid delaying the nurse", "Estimate based on yesterday"], "a": 1, "e": "Be clear about what you know and what you did not observe. Accurate information supports safe decisions.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 32, "q": "A client nods while you explain a task, but looks confused. What is the best next step?", "opts": ["Assume the nod means understanding", "Repeat the same explanation much louder", "Use simpler language and ask them to explain their understanding", "Ask a co-worker to obtain consent without explanation"], "a": 2, "e": "A nod does not always indicate understanding. Use plain language and check comprehension respectfully.", "cat": "Communication", "photo": null, "note": null}, {"id": 33, "q": "A client needs more time to speak after a stroke. What is best?", "opts": ["Finish every sentence for them", "Allow time and use communication aids in the care plan", "Pretend you understand to avoid embarrassment", "Direct all conversation to visitors"], "a": 1, "e": "Allow time for expression and use agreed communication supports. Confirm meaning rather than assuming it.", "cat": "Communication", "photo": null, "note": null}, {"id": 34, "q": "During handover, two staff discuss a resident in a public elevator. What should you do?", "opts": ["Join in quietly", "Record the conversation on your phone", "Suggest continuing in a private, appropriate area", "Allow it because no names were used"], "a": 2, "e": "Care information belongs in an appropriate private setting. A person can be identified even without their name.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 35, "q": "A resident asks you to keep a large cash gift for helping them. What is best?", "opts": ["Accept it if nobody sees", "Share it with your co-worker", "Accept it and provide extra care", "Politely decline and follow the employer’s gift policy"], "a": 3, "e": "Maintain professional boundaries and follow policy. Care must not depend on gifts.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 36, "q": "A resident says, “I feel lonely since my partner died.” Which response is therapeutic?", "opts": ["At least you have other family", "You need to keep yourself busy", "Would you like to tell me about your partner?", "You will feel better soon"], "a": 2, "e": "Invite the person to share if they wish. Avoid minimizing grief or predicting how quickly it will improve.", "cat": "Health Across the Life Span", "photo": null, "note": null}, {"id": 37, "q": "A client refuses assistance with dressing. There is no immediate danger. What should you do?", "opts": ["Respect the refusal, explore the reason and report or document as appropriate", "Dress them because it is in the plan", "Threaten to cancel their breakfast", "Ask another aide to force the task"], "a": 0, "e": "Consent is ongoing. Explore preferences or concerns without pressure, offer alternatives and communicate relevant information.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 38, "q": "A colleague gives you useful feedback about your communication. What is the most professional response?", "opts": ["Explain why the colleague is wrong before listening", "Ignore the feedback", "Discuss their mistakes instead", "Listen, clarify examples and consider how to improve"], "a": 3, "e": "Constructive feedback supports learning. Clarifying examples helps identify a useful improvement.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 39, "q": "A resident tells you their pain is worse today. What should you do?", "opts": ["Wait until the end of the week to see a pattern", "Listen, report promptly to the nurse and provide comfort within the care plan", "Tell them the pain is normal for their age", "Increase the medication dose"], "a": 1, "e": "Take the report seriously and communicate the change. Provide authorized comfort measures without independently changing treatment.", "cat": "Provision of Care", "photo": null, "note": null}, {"id": 40, "q": "Which statement best describes advocacy?", "opts": ["Making all decisions for the client", "Speaking for every family member", "Supporting the client’s rights, preferences and access to appropriate care", "Agreeing with every request regardless of safety"], "a": 2, "e": "Advocacy supports the person’s voice and rights while working with the team to address care needs.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 41, "q": "A client’s room is cluttered and the call bell is out of reach. What should you do?", "opts": ["Wait for housekeeping to address everything", "Remove immediate hazards safely and place the call bell within reach", "Tell the client not to move all day", "Move all personal items without asking"], "a": 1, "e": "Address environmental safety while respecting belongings and preferences. Ensure the client can request help.", "cat": "Safety", "photo": null, "note": null}, {"id": 42, "q": "Why should an HCA perform hand hygiene after removing gloves?", "opts": ["Gloves replace hand hygiene unless torn", "Only to remove visible powder", "Hands may become contaminated during glove removal", "It is only needed before eating"], "a": 2, "e": "Gloves do not eliminate the need for hand hygiene; hands can be contaminated during use or removal.", "cat": "Safety", "photo": null, "note": null}, {"id": 43, "q": "A client’s care plan has changed since your last shift. What should guide today’s care?", "opts": ["Your memory of the previous routine", "The updated plan, with clarification of anything unclear", "Whatever is quickest", "The roommate’s advice"], "a": 1, "e": "Review the current plan and clarify changes so your actions match current needs and instructions.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 44, "q": "Which action supports person-centred care?", "opts": ["Using the same routine for every resident", "Asking the resident what matters to them when planning daily care", "Avoiding choices because they take time", "Letting family preferences automatically replace the resident’s"], "a": 1, "e": "The individual’s goals and preferences guide person-centred care, alongside assessed needs and safe practice.", "cat": "Provision of Care", "photo": null, "note": null}, {"id": 45, "q": "A resident has experienced several losses and wants to share memories of their life. What is the most supportive response?", "opts": ["Tell them to focus only on the present", "Avoid emotional subjects", "Listen with interest and allow them to share at their own pace", "Change the topic when they mention loss"], "a": 2, "e": "Listening to meaningful memories can support identity and connection. Let the resident guide the conversation and respect their wish to stop.", "cat": "Health Across the Life Span", "photo": null, "note": null}, {"id": 46, "q": "A resident is upset about a change in their room. What is the best opening response?", "opts": ["The change has already been decided", "I can see this has upset you. What concerns you most?", "You will get used to it", "Other residents have bigger problems"], "a": 1, "e": "Acknowledge the emotion and invite the resident’s perspective before offering solutions.", "cat": "Communication", "photo": null, "note": null}, {"id": 47, "q": "You discover that you forgot to report a relevant observation earlier. What should you do?", "opts": ["Report it promptly now, including when you observed it, and document accurately", "Change the recorded time to make it appear recent", "Wait until the next scheduled handover", "Ask a colleague to say they reported it"], "a": 0, "e": "Correct omissions honestly and promptly. Accurate times help the team understand the sequence of events.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 48, "q": "A child in your care wants to choose between two suitable shirts. What is the best response?", "opts": ["Choose for the child to save time", "Offer the two safe choices and allow the child to decide", "Offer every item of clothing at once", "Tell the child they are too young to make choices"], "a": 1, "e": "Age-appropriate choices support developing independence. Offer manageable, safe options while providing needed assistance.", "cat": "Health Across the Life Span", "photo": null, "note": null}, {"id": 49, "q": "A resident expresses a wish that differs from their family’s preference. The resident can make this decision. What should you do?", "opts": ["Automatically follow the family’s request", "Avoid documenting the disagreement", "Support the resident’s choice and communicate the issue to the appropriate team member", "Make the decision yourself"], "a": 2, "e": "A person able to make the decision retains their voice and choice. The team can help address disagreements respectfully.", "cat": "HCA Role and Responsibility", "photo": null, "note": null}, {"id": 50, "q": "A care task has been delayed because the required equipment is unavailable. What should you do?", "opts": ["Use any nearby equipment without checking", "Say nothing unless someone asks", "Record the task as completed", "Inform the appropriate team member and arrange a safe alternative or revised timing"], "a": 3, "e": "Communicate barriers promptly. Do not improvise an unsafe method or inaccurately record completion.", "cat": "Collaborative Care", "photo": null, "note": null}, {"id": 51, "q": "When assisting a client to dress in an outfit brought in by their family for a special celebration, the client states they are more comfortable wearing their usual casual clothing. How should the health care aide respond?", "opts": ["Contact family to discuss client choice of clothing", "Persuade client to dress in clothing provided by family", "Assist client to dress in preferred clothing", "Advise client their family will be disappointed with clothing choice"], "a": 2, "e": "Support the client’s choice of clothing. Respecting personal preferences promotes autonomy, comfort and dignity; pressure from staff or family is not a reason to override that choice.", "cat": "HCA Role and Responsibility", "photo": "01-13804.jpg", "note": null}, {"id": 52, "q": "A health care aide (HCA) observes several bruises on both upper arms of a 50-year-old while assisting them with a shower. The client is unwilling to talk about the bruises. What should the HCA do?", "opts": ["Call police and report suspected abuse", "Continue with shower and provide support", "Contact client’s family and communicate concerns", "Contact client’s case manager and report observations"], "a": 3, "e": "Report the observations promptly to the case manager or appropriate supervisor and document facts objectively. Do not pressure the client or investigate independently. Follow all required abuse-reporting procedures; notifying a supervisor alone may not fulfil a legal reporting duty. Seek emergency help for immediate danger.", "cat": "Safety", "photo": "03-13802.jpg", "note": null}, {"id": 53, "q": "A 23-year-old transgender client asks to be called by a name that is different from admission documents. How should the health care aide respond?", "opts": ["Use preferred name", "Check with supervisor", "Use legal name client was given at birth", "Avoid calling client by name to prevent embarrassment"], "a": 0, "e": "Use the name the client asks you to use. This supports respect and trust. Continue following approved identification and documentation procedures; a difference from the admission record is not a reason to ignore their requested name.", "cat": "Communication", "photo": "05-13800.jpg", "note": null}, {"id": 54, "q": "A licensed practical nurse (LPN) asks a health care aide (HCA) to insert an indwelling catheter. How should the HCA respond?", "opts": ["Explain skill is outside scope of practice", "Request supervision while performing task", "Advise employer policies need to be verified", "Suggest LPN ask a more experienced HCA"], "a": 0, "e": "The likely intended answer is to explain that this is outside the HCA’s role in the situation described. Routine catheter care and inserting a catheter are different tasks. A nurse’s request or supervision alone does not establish competence or authorization. In actual practice, verify current regulatory requirements, employer policy, the care plan and your own training before accepting any such task.", "cat": "HCA Role and Responsibility", "photo": "06-13799.jpg", "note": "Context-sensitive study answer: the photo gives no official key or information about special training or authorization. Do not treat this item as a complete statement of current scope rules."}, {"id": 55, "q": "A note in the care plan indicates an 82-year-old client diagnosed with chronic obstructive pulmonary disease can go outside to smoke. What is the appropriate response when the client states they are going outside?", "opts": ["Tell them they should stop smoking", "Tell them smoking makes them smell bad", "Suggest they ask their primary care provider for a nicotine patch", "Ask they notify health care aide when they are back inside"], "a": 3, "e": "Follow the documented plan and respectfully ask the client to let you know when they return. Avoid shaming or imposing your preferences. Follow any supervision, designated-area and fire-safety requirements; smoking around oxygen is unsafe. Report new safety concerns to the nurse.", "cat": "HCA Role and Responsibility", "photo": "07-13798.jpg", "note": null}, {"id": 56, "q": "A health care aide (HCA) is assigned to take blood pressures on four clients. The second client’s blood pressure is 202/149. What should the HCA do next?", "opts": ["Change blood pressure cuff to smaller size", "Write down blood pressure on vital sign record", "Finish taking other assigned blood pressures", "Take blood pressure again to verify reading"], "a": 3, "e": "Among these options, repeat the measurement promptly using correct technique and an appropriately sized cuff. This is a very high reading: alert the nurse promptly and follow the urgent-response protocol. Do not continue routine rounds or merely document it. If chest pain, breathing difficulty, new weakness or other emergency symptoms are present, activate emergency help without delaying for another measurement.", "cat": "Safety", "photo": "08-13797.jpg", "note": "The answer choices omit prompt reporting. Rechecking must not delay urgent assessment or emergency assistance."}, {"id": 57, "q": "A client suddenly becomes disoriented to time and place, and is experiencing hallucinations. What is the first action the health care aide should take?", "opts": ["Call family", "Take vital signs", "Turn on soothing music", "Inform supervisor immediately"], "a": 3, "e": "Sudden confusion and hallucinations are an acute change that needs urgent assessment. Notify the supervisor or nurse immediately, stay with the client as needed for safety and follow the emergency protocol if the person is seriously unwell. Do not delay reporting to try music or contact family first.", "cat": "Collaborative Care", "photo": "09-13796.jpg", "note": null}, {"id": 58, "q": "What is a symptom of orthostatic hypotension?", "opts": ["Headache", "Dizziness", "Rapid respiration", "Nausea"], "a": 1, "e": "Dizziness or light-headedness when standing is the most characteristic answer here. Orthostatic hypotension is a drop in blood pressure with a change to an upright position. Help the client sit or lie safely and report symptoms. Other symptoms, including nausea, may also occur, so the wording is not exclusive.", "cat": "Health Across the Life Span", "photo": "10-13795.jpg", "note": null}, {"id": 59, "q": "A 54-year-old client returned home following shoulder surgery. The care plan states active-assistive range of motion (ROM) to the left shoulder two times a day. What is the correct action for the health care aide to take?", "opts": ["Direct client to move the shoulder joint", "Gently push the joint past the point of resistance", "Help client move the shoulder joint slowly and smoothly", "Start ROM at the client’s neck and work down to the affected joint"], "a": 2, "e": "Active-assisted ROM means the client participates in the movement with assistance. Help with slow, smooth movements as prescribed in the postoperative care plan. Never force the joint past resistance or pain, and report concerns.", "cat": "Provision of Care", "photo": "02-13793.jpg", "note": null}, {"id": 60, "q": "Which government act holds health care organizations accountable for the way they collect, use, and share information?", "opts": ["Health Information Act", "Electronic Health Records Act", "Government Organizational Act", "Protection of Privacy Act"], "a": 0, "e": "In the Alberta health-care context, the Health Information Act governs the collection, use and disclosure of health information by custodians and applies to their affiliates. Follow confidentiality requirements and access information only as authorized for your role.", "cat": "HCA Role and Responsibility", "photo": "03-13792.jpg", "note": null}, {"id": 61, "q": "What action demonstrates infection prevention and control practices?", "opts": ["Wearing gloves for all personal care", "Wearing the same gloves between clients", "Practicing sterile technique when giving mouth care", "Donning and doffing appropriate personal protective equipment"], "a": 3, "e": "Choose appropriate PPE for the exposure risk and put it on and remove it correctly. Perform hand hygiene as required. Gloves are not needed for every personal-care task and must not be reused between clients. Routine mouth care uses clean technique rather than sterile technique.", "cat": "Safety", "photo": "06-13789.jpg", "note": null}, {"id": 62, "q": "A client who has had a stroke needs to relearn how to get dressed. Which care team member would most likely help with this task?", "opts": ["Physical therapist", "Massage therapist", "Recreational therapist", "Occupational therapist"], "a": 3, "e": "An occupational therapist helps clients regain skills for daily activities such as dressing, washing and eating, including adaptive techniques or equipment. Physical therapists focus on movement and mobility; both may contribute to stroke rehabilitation.", "cat": "Collaborative Care", "photo": "07-13788.jpg", "note": null}, {"id": 63, "q": "What would be most effective when communicating with a client diagnosed with progressive dementia?", "opts": ["Limit use of humour", "Minimize distractions", "Restrict direct eye contact", "Use an assistive communication device"], "a": 1, "e": "A calm environment with fewer distractions helps the client focus on communication. Speak clearly, use simple sentences and allow time to respond. Adapt communication to the individual; humour, appropriate eye contact and communication aids can help when suited to the person.", "cat": "Communication", "photo": "08-13787.jpg", "note": null}, {"id": 64, "q": "Where in the body is a percutaneous endoscopic gastrostomy (PEG) tube located?", "opts": ["Rectum", "Stomach", "Large intestine", "Small intestine"], "a": 1, "e": "A PEG tube passes through the abdominal wall into the stomach. It provides a route for prescribed nutrition, fluids and medicines when needed. A tube ending in the small intestine is a different type of feeding access.", "cat": "Provision of Care", "photo": "10-13785.jpg", "note": null}, {"id": 65, "q": "Which of the following bathroom items is most likely to be a fall risk?", "opts": ["Low toilet", "Non-slip mat", "Tub with handrails", "Toilet seat grab bars"], "a": 0, "e": "A low toilet can make sitting down and standing up difficult, especially with reduced strength or balance. Properly installed grab bars and secure non-slip mats help reduce risk. Equipment height and fit should be assessed for the individual.", "cat": "Safety", "photo": "02-13783.jpg", "note": null}, {"id": 66, "q": "What is included when caring for a client who has an indwelling urinary catheter?", "opts": ["Attach the bag to the bed rail", "Provide catheter care every 4 hours", "Secure catheter to client thigh", "Change catheter every two days"], "a": 2, "e": "Among these options, securing the catheter to the thigh is the best answer because appropriate securement prevents pulling and urethral injury. Follow the prescribed securement device and site; these can vary. Keep the drainage bag below bladder level, off the floor and attached to an appropriate fixed support, not a moving side rail. Follow the care plan for hygiene and catheter changes rather than a universal four-hour or two-day schedule.", "cat": "Provision of Care", "photo": "03-13782.jpg", "note": "Securement site and device depend on the client, catheter and care plan. Perform only care you are trained and authorized to provide."}, {"id": 67, "q": "What is the expected oral temperature range for an adult?", "opts": ["33.0°C–34.5°C", "35.0°C–36.0°C", "36.0°C–37.5°C", "37.5°C–39.5°C"], "a": 2, "e": "Of these choices, 36.0°C–37.5°C best represents the expected adult oral temperature range. The average is about 37°C, but temperature varies with the person, time of day, measurement site and device. Compare with the client’s baseline and report concerning changes according to policy.", "cat": "Health Across the Life Span", "photo": "05-13780.jpg", "note": null}, {"id": 68, "q": "A health care aide repeatedly accepts cash from a client. This is an example of which type of abuse?", "opts": ["Neglect", "Older-person", "Financial", "Emotional"], "a": 2, "e": "Financial is the best answer in this scenario. Repeatedly accepting a client’s money for personal benefit can exploit the care relationship and breach professional boundaries. Follow employer rules about gifts and report concerns. A legal finding of abuse depends on the facts; a selected answer in the photo is not an official answer key.", "cat": "HCA Role and Responsibility", "photo": "07-13778.jpg", "note": null}, {"id": 69, "q": "How should a health care aide provide assistance during mealtime for a client who has a visual impairment?", "opts": ["Use patterned cups and plates", "Apply clothing protector", "Ensure bright lighting in the area", "Describe location of items on plate"], "a": 3, "e": "Describe the food and where it is on the plate, using the clock-face method if the client finds it helpful. This supports choice and independence. Ask what assistance is preferred. Suitable glare-free lighting and plain contrasting dishes can also help; bright lighting alone does not orient the person to the food.", "cat": "Provision of Care", "photo": "08-13777.jpg", "note": null}, {"id": 70, "q": "The health care aide (HCA) notices that there is medication missing from the client’s blister pack. What should the HCA do?", "opts": ["Report to supervisor", "Document and continue care", "Ask co-worker about medications", "Ask client why medication is missing"], "a": 0, "e": "Report the discrepancy promptly to the supervisor or authorized supervising health professional, and document according to policy. Do not assume the medication was taken or independently replace or give another dose. Follow the supervising professional’s instructions to avoid an omitted or duplicate dose.", "cat": "Collaborative Care", "photo": "09-13776.jpg", "note": null}, {"id": 71, "q": "The health care aide (HCA) completes vital signs on a 74-year-old client who smokes: BP 189/99, P 78, R 17, SpO₂ 97% and T 35.9°C (tympanic). What should the HCA do next?", "opts": ["Retake oxygen saturation", "Ask client when they last smoked", "Communicate temperature to supervisor", "Report blood pressure reading to supervisor"], "a": 3, "e": "Report the markedly elevated blood pressure promptly to the supervisor or nurse. A systolic pressure above 180 requires prompt attention even when the diastolic pressure is below 120. Follow instructions for repeat measurement and assessment; do not dismiss the result as smoking-related. If chest pain, shortness of breath, new weakness or other emergency symptoms occur, activate emergency help. Include the other readings, including the low temperature, in the report.", "cat": "Safety", "photo": "10-13775.jpg", "note": null}, {"id": 72, "q": "A home care client tells the health care aide (HCA) that they had the flu yesterday and are feeling weak today. How should the HCA respond?", "opts": ["Provide care and document", "Reschedule visit and document", "Call supervisor and ask for direction", "Take vital signs and notify supervisor"], "a": 2, "e": "New weakness after an illness is a change to report. Calling the supervisor for direction is the safest choice when the care plan, equipment and authorization to take vital signs are not specified. If trained, equipped and authorized, taking vital signs promptly and reporting them may also be appropriate. Do not delay urgent help for severe weakness, breathing difficulty, confusion or other emergency signs. Use appropriate infection precautions.", "cat": "Collaborative Care", "photo": "02-13773.jpg", "note": "Context-sensitive: the photo provides no official key. Option D may be expected if taking vital signs is already authorized. This app uses C because that authorization is not stated."}, {"id": 73, "q": "What is the main reason for clear, appropriate communication?", "opts": ["Shows assertiveness and professionalism", "Needed for safe effective care", "Decreases client hesitancy to cooperate", "Shows a focus on client’s physical needs"], "a": 1, "e": "Clear communication helps clients and care team members understand needs, instructions and changes, reducing misunderstandings and supporting safe, effective care. Professionalism and cooperation may also improve, but safety and effective care are the central purpose.", "cat": "Communication", "photo": "03-13772.jpg", "note": null}, {"id": 74, "q": "A client receiving end-of-life care tells the health care aide (HCA) they are afraid they might die alone. How should the HCA respond?", "opts": ["Report to supervisor", "Tell client they have nothing to fear", "Explain dying is a normal part of life", "Suggest client share fears with loved ones"], "a": 3, "e": "Of these choices, inviting the client to share fears with loved ones is the most supportive direct response, if the client wishes. First listen and acknowledge the fear rather than dismissing it. Offer help connecting with chosen supports and tell the care team so a support plan can be arranged. Do not promise that someone will always be present.", "cat": "Communication", "photo": "07-13768.jpg", "note": "The ideal first response is empathetic listening, which is not offered among the choices. Involve loved ones only with the client’s agreement."}, {"id": 75, "q": "A 70-year-old client diagnosed with middle stage dementia enjoys ironing clothes but has burned themselves several times with the iron. What is the best action to continue supporting the client’s routine at home?", "opts": ["Remove iron from home", "Allow client to continue ironing", "Suggest spouse does the ironing", "Ask family to provide a non-functioning iron"], "a": 3, "e": "Among these options, a safe non-heating substitute can preserve a familiar activity while reducing burn risk. Work with the client, family and care team to adapt the routine and assess safety. A broken electrical appliance is not automatically safe: it must be unable to heat or be energized and have no exposed wiring or other hazards. Offer another meaningful task, such as folding clothes, if the substitute causes frustration.", "cat": "Health Across the Life Span", "photo": "08-13767.jpg", "note": "This is an inference from person-centred activity and safety principles, not a blanket recommendation to use damaged electrical equipment."}, {"id": 76, "q": "A health care aide (HCA) and a co-worker disagree about who is going to shower a client. How should the HCA proceed?", "opts": ["Shower client", "Report issue to supervisor", "Address issue with co-worker", "Ask client who they want to assist them"], "a": 2, "e": "Discuss the disagreement calmly and privately with the co-worker, clarify the assignment and agree on how to meet the client’s care needs. Respect the client’s preferences without asking them to settle a staff dispute. Involve the supervisor if the disagreement remains unresolved or care or safety is at risk.", "cat": "Collaborative Care", "photo": "09-13766.jpg", "note": null}, {"id": 77, "q": "The health care aide (HCA) answers a call from a primary care provider who wants to provide an immediate order for a client. What should the HCA do?", "opts": ["Transfer the call to a unit clerk to transcribe", "Request primary care provider email it to the unit", "Ask primary care provider to hold while getting supervisor", "Write down primary care provider’s orders and notify supervisor"], "a": 2, "e": "Promptly connect the prescriber with the nurse or other professional authorized to receive the order. Asking the caller to hold while getting the appropriate supervisor is the best option. Do not independently accept or implement a clinical telephone order outside your role. Follow the organization’s urgent-call procedure.", "cat": "HCA Role and Responsibility", "photo": "01-13764.jpg", "note": null}, {"id": 78, "q": "Attempting to frighten, control, or intimidate a client through verbal commands is what type of abuse?", "opts": ["Emotional", "Physical", "Battery", "Manipulation"], "a": 0, "e": "Threatening or intimidating words can cause fear and psychological harm, making emotional abuse the best category. Manipulation may describe a tactic, but emotional abuse identifies the type of harm in this scenario. Protect the client and report concerns through the required process.", "cat": "Safety", "photo": "03-13762.jpg", "note": null}, {"id": 79, "q": "During a home care visit, why should the health care aide use their cell phone in a private area rather than at the client’s bedside?", "opts": ["Maintains personal privacy", "Demonstrates respect for client", "Decreases risk of dropping it", "Lowers transmission of microorganisms"], "a": 1, "e": "Using a phone away from the bedside when appropriate demonstrates respect for the client and avoids interrupting focused care. Follow workplace phone rules, take personal calls only at permitted times, and ensure the client is safe before stepping away. Private location alone does not replace hand hygiene or device cleaning.", "cat": "HCA Role and Responsibility", "photo": "04-13761.jpg", "note": null}, {"id": 80, "q": "The care plan states the client is to wash their own face, hands, and chest. The client refuses to do this stating it is the health care aide’s (HCA) job. How should the HCA respond?", "opts": ["Advise client they must follow the care plan", "Provide client with washcloth and leave room", "Agree to wash them despite what the care plan says", "Explain importance of maintaining independence"], "a": 3, "e": "Explain respectfully how doing the parts they can manage helps preserve independence, and offer encouragement and appropriate support. Ask whether pain, fatigue or another concern is making the task difficult. Do not force the client or leave them unsupported; respect refusal and report changes or ongoing difficulty so the plan can be reviewed.", "cat": "Provision of Care", "photo": "05-13760.jpg", "note": null}, {"id": 81, "q": "A 69-year-old client with dementia is screaming and yelling. How should the health care aide respond?", "opts": ["Relocate client", "Use therapeutic touch to calm", "Isolate client to protect others", "Tell client to stop yelling"], "a": 1, "e": "Among these choices, gentle reassuring touch may help if the client welcomes it and their care plan supports it. Approach calmly, acknowledge distress and look for unmet needs such as pain, fear or toileting. Do not touch unexpectedly or persist if it increases distress. Reduce noise and offer a quieter place when appropriate; get help if safety is at risk and report new or worsening behaviour.", "cat": "Communication", "photo": "08-13758.jpg", "note": "Context-sensitive: B is interpreted as ordinary comforting touch, not an energy-based treatment. Touch is not always appropriate; a quiet relocation may be better when overstimulation is the cause."}, {"id": 82, "q": "A health care aide (HCA) observes an 81-year-old client drop their medication on the floor. What action should the HCA take?", "opts": ["Place medication in garbage and report to supervisor", "Pick the medication up, wipe it off and give it back to client", "Document the wastage on the medication incident report form", "Discard medication according to agency policy and report to supervisor"], "a": 3, "e": "Follow the agency’s medication-disposal procedure and promptly report the dropped dose to the supervising professional. Do not give contaminated medication back or place it in ordinary garbage unless the approved procedure specifically allows this. Follow instructions for replacement and documentation; do not independently give an extra dose.", "cat": "Safety", "photo": "07-13757.jpg", "note": null}, {"id": 83, "q": "A client has misplaced their hearing aids. What is the best way to communicate with this client?", "opts": ["Write out message", "Choose words carefully", "Speak loudly and clearly", "Face client and speak softly"], "a": 0, "e": "Of these choices, writing the message is a useful alternative when hearing aids are unavailable, provided the client can see, read and understand it. Ask their preferred method, face them and reduce background noise. Shouting may distort speech, and speaking too softly may be ineffective. Confirm understanding and help locate the hearing aids.", "cat": "Communication", "photo": "09-13756.jpg", "note": null}, {"id": 84, "q": "What is the name of the condition when kidneys are unable to remove waste products from the blood?", "opts": ["Oliguria", "Diuresis", "Renal failure", "Renal calculi"], "a": 2, "e": "Renal failure means kidney function is severely impaired, so waste products and excess fluid can build up. Oliguria means reduced urine output, diuresis means increased urine production, and renal calculi are kidney stones.", "cat": "Health Across the Life Span", "photo": "03-13736.jpg", "note": null}, {"id": 85, "q": "What is a common factor in the development of depression among older adults?", "opts": ["Poor nutrition", "Independent living", "Raising children", "Financial stability"], "a": 0, "e": "Poor nutrition is the best answer among these choices. Nutrition and depression can affect each other: inadequate intake can contribute to poor physical and mental health, while depression can reduce appetite. Depression has many possible contributors, including illness, loss and isolation; it is not a normal or inevitable part of aging. Independent living alone does not mean social isolation.", "cat": "Health Across the Life Span", "photo": "05-13734.jpg", "note": null}, {"id": 86, "q": "A health care aide has shared a client’s name and diagnosis on social media. What is this an example of?", "opts": ["Negligence", "Slander", "Breach of privacy", "Access to information"], "a": 2, "e": "Sharing identifiable client health information publicly without authorization breaches privacy and confidentiality. Accessing information for care does not authorize posting it online. Report a privacy incident promptly through the organization’s process.", "cat": "HCA Role and Responsibility", "photo": "06-13733.jpg", "note": null}, {"id": 87, "q": "What is the ideal temperature for microorganisms to grow on food?", "opts": ["Between 4°C and 60°C", "Between 15°C and 80°C", "Between 20°C and 74°C", "Between 27°C and 100°C"], "a": 0, "e": "Between 4°C and 60°C is the food temperature danger zone used in Canadian food-safety guidance. Many harmful bacteria can multiply in this range. Keep cold food at 4°C or below and hot food at 60°C or above. This is a safety range, not a single ideal growth temperature for every microorganism.", "cat": "Safety", "photo": "07-13732.jpg", "note": null}, {"id": 88, "q": "What should the health care aide ensure regarding the client before performing a one-person assist transfer?", "opts": ["Wearing socks", "Wearing reading glasses", "Alert and able to cooperate", "Transfer belt applied under axilla"], "a": 2, "e": "The client must be able to understand and cooperate with the transfer. This alone is not enough: confirm the care plan, current weight-bearing ability, balance, required equipment and assistance level before proceeding. Use appropriate non-slip footwear. A transfer belt is fitted as instructed around the appropriate waist or trunk area, not under the armpits. Stop and seek help if abilities have changed.", "cat": "Safety", "photo": "09-13730.jpg", "note": null}, {"id": 89, "q": "What must the health care aide do first before assisting a client into a motorized wheelchair?", "opts": ["Apply safety belt around client", "Turn off power source", "Attach the leg and armrests", "Ensure wheels are turned to the right"], "a": 1, "e": "Of these choices, switch off the wheelchair’s power before the transfer to prevent unintended movement from the controls. Ensure the chair is stable with its brakes engaged according to the manufacturer’s instructions, not in freewheel mode. Follow the transfer plan and move footrests or other parts out of the way as needed.", "cat": "Safety", "photo": "10-13729.jpg", "note": null}];
